(()=>{const t=document.getElementById("slides"),n=[...t.children],i=document.getElementById("pos"),s=document.getElementById("prev"),c=document.getElementById("next"),o=()=>Math.round(Math.abs(t.scrollLeft)/(t.clientWidth+10)),d=e=>n[Math.max(0,Math.min(n.length-1,e))].scrollIntoView({behavior:"smooth",inline:"center",block:"nearest"}),l=()=>{const e=o();i.textContent=`${e+1} / ${n.length}`,s.disabled=e===0,c.disabled=e===n.length-1};t.addEventListener("scroll",()=>requestAnimationFrame(l),{passive:!0}),s.addEventListener("click",()=>d(o()-1)),c.addEventListener("click",()=>d(o()+1)),l()})();
